B64_A2
verify "$TMPD/a2" "${NEW_ADD[2]}" "dashboard/src/app/(admin)/credits/page.tsx"

grep -q 'export async function reserve' "$TMPD/a0" || die "credits.ts payload is wrong. Aborting."
grep -q 'myCredits' "$TMPD/a1" || die "backend/src/routes/credits.ts payload is wrong. Aborting."
grep -q 'CreditsPage' "$TMPD/a2" || die "dashboard/src/app/(admin)/credits/page.tsx payload is wrong. Aborting."
grep -q -- '024_credits' "$TMPD/m3" || die "migrations.ts payload is wrong. Aborting."
grep -q -- '/credits/grant' "$TMPD/m4" || die "admin.ts payload is wrong. Aborting."
grep -q -- 'creditsRouter' "$TMPD/m0" || die "index.ts payload is wrong. Aborting."
grep -q -- '"notCharging"' "$TMPD/m13" || die "en.json payload is wrong. Aborting."
grep -q -- '"errors"' "$TMPD/m13" || die "en.json payload lost 15b3. Aborting."
grep -q -- 'CreditsSection' "$TMPD/m9" || die "wallet page payload is wrong. Aborting."
grep -q -- '"/credits"' "$TMPD/m6" || die "Shell.tsx payload is wrong. Aborting."
say "20 payloads decoded and verified."

# ---- backups ----
mkdir -p "$BAKDIR/$STAMP"
for f in "${MOD[@]}"; do cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; done
for f in ${ADD[@]+"${ADD[@]}"}; do if [ -f "$f" ]; then cp "$f" "$BAKDIR/$STAMP/$(bname "$f")"; fi; done
say "Backups saved to $BAKDIR/$STAMP/"

rollback() {
  restore_from "$BAKDIR/$STAMP"
  die "$1 All files restored from $BAKDIR/$STAMP."
}

# ---- write ----
i=0; for f in ${ADD[@]+"${ADD[@]}"}; do mkdir -p "$(dirname "$f")"; cp "$TMPD/a$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do cp "$TMPD/m$i" "$f" || rollback "Could not write $f."; i=$((i+1)); done

i=0; for f in ${ADD[@]+"${ADD[@]}"}; do [ "$(sha "$f")" = "${NEW_ADD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done
i=0; for f in "${MOD[@]}"; do [ "$(sha "$f")" = "${NEW_MOD[$i]}" ] || rollback "$f write verify failed."; i=$((i+1)); done

say "Applied Part 16a (credits: ledger, prices, free credits, Wallet page)."
say "Migration 024_credits runs by itself when the backend starts."
say "Charging stays off: every price starts at 0 and nothing is taken from a balance."
say "Verify before pushing:"
say "  (cd backend && npx tsc --noEmit) && (cd frontend && npx tsc --noEmit) && (cd dashboard && npx tsc --noEmit)"
say "Undo: ./vm_credits_a.sh --revert"
